mapper.select:
SELECT * FROM ( SELECT p.products_no, p.products_nm, m.model_no, m.model_nm, b.brand_nm, CASE WHEN p.products_status = '판매중단' THEN '판매중단' WHEN EXISTS ( SELECT 1 FROM sell_products sp WHERE sp.products_no = p.products_no AND sp.use_status = '사용중' ) THEN '활성화' ELSE '비활성화' END AS products_status, IFNULL(f.file_path, '/manage/assets/imgs/theme/upload.svg') AS products_image, DATE_FORMAT(p.register_date, '%Y-%m-%d %H:%i:%s') AS register_date, DATE_FORMAT(p.revision_date, '%Y-%m-%d %H:%i:%s') AS revision_date, m.product_category_no, b.brand_no, m.item_no FROM products p INNER JOIN model m ON p.model_no = m.model_no INNER JOIN brand b ON m.brand_no = b.brand_no LEFT JOIN files f ON m.model_no = f.ref_id AND f.file_type = 'mainImage' ) temp
AND products_nm LIKE CONCAT('%', #{searchValue}, '%')
AND brand_nm LIKE CONCAT('%', #{searchValue}, '%')
AND product_category_no = #{categoryNo}
AND products_status = #{status}

SELECT model_no AS modelNo, model_nm AS modelNm FROM model WHERE product_category_no = #{categoryNo} AND item_no = #{itemNo}
AND brand_no = #{brandNo}
AND use_status = '사용중'
